function hashRememberToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// Issues a url-safe remember-me token for userId. The raw token is returned
// only here; server-side we keep just its sha256, so the token cannot be
// recovered from our storage.
function generateRememberToken(userId) {
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('userId must be a non-empty string');
  }
  // 256 bits of CSPRNG entropy, base64url => url-safe, no padding.
  const token = crypto.randomBytes(32).toString('base64url');
  const now = Date.now();
  rememberTokens.set(hashRememberToken(token), {
    userId,
    createdAt: now,
    expiresAt: now + REMEMBER_TOKEN_TTL_MS,
  });
  return token;
}

// Returns { userId } for a live token, or null. Expired tokens are dropped.
function validateRememberToken(token) {
  if (typeof token !== 'string' || token === '') return null;
  const hash = hashRememberToken(token);
  const record = rememberTokens.get(hash);
  if (!record) return null;
  if (Date.now() >= record.expiresAt) {
    rememberTokens.delete(hash);
    return null;
  }
  return { userId: record.userId };
}

module.exports = {
  login,
  getSession,
  generateSessionId,
  generateRememberToken,
  validateRememberToken,
};

