'use strict';
const { test } = require('node:test');
const assert = require('node:assert');
const {
  login,
  getSession,
  generateRememberToken,
  validateRememberToken,
} = require('../src/auth.js');

test('login happy path returns a session', () => {
  const res = login('alice', 'wonderland');
  assert.strictEqual(res.ok, true);
  assert.ok(res.sessionId.length > 0);
  assert.strictEqual(getSession(res.sessionId).userId, 'u1');
});

test('wrong password is rejected', () => {
  const res = login('alice', 'nope');
  assert.strictEqual(res.ok, false);
  assert.strictEqual(res.sessionId, undefined);
});

test('remember token round-trips to its user', () => {
  const token = generateRememberToken('u1');
  assert.deepStrictEqual(validateRememberToken(token), { userId: 'u1' });
});

test('remember token is url-safe and high-entropy', () => {
  const token = generateRememberToken('u1');
  assert.match(token, /^[A-Za-z0-9_-]+$/);
  assert.strictEqual(token, encodeURIComponent(token));
  // 32 random bytes in base64url, unpadded
  assert.strictEqual(token.length, 43);
});

test('remember tokens are unique per call', () => {
  const tokens = new Set();
  for (let i = 0; i < 100; i++) tokens.add(generateRememberToken('u1'));
  assert.strictEqual(tokens.size, 100);
});

test('unknown, empty and non-string tokens are rejected', () => {
  assert.strictEqual(validateRememberToken('not-a-real-token'), null);
  assert.strictEqual(validateRememberToken(''), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken({}), null);
});

test('a tampered token does not validate', () => {
  const token = generateRememberToken('u1');
  const tampered = token.slice(0, -1) + (token.endsWith('A') ? 'B' : 'A');
  assert.strictEqual(validateRememberToken(tampered), null);
  // the original still works
  assert.deepStrictEqual(validateRememberToken(token), { userId: 'u1' });
});

test('generateRememberToken rejects a missing userId', () => {
  assert.throws(() => generateRememberToken(), TypeError);
  assert.throws(() => generateRememberToken(''), TypeError);
});
